   542  /*
   543   * Note we also need to scan through the record encoding map to
   544   * see which data series share the same block, either external or
   545   * CORE. For example if we need the BF data series but MQ and CF
   546   * are also encoded in the same block then we need to add those in
   547   * as a dependency in order to correctly decode BF.
   548   *
   549   * Returns 0 on success
   550   *        -1 on failure
   551   */
   552  int cram_dependent_data_series(cram_fd *fd,
   553                                 cram_block_compression_hdr *hdr,
   554                                 cram_slice *s) {
   555      int *block_used;
   556      int core_used = 0;
   557      int i;
   558      static int i_to_id[] = {
   559          DS_BF, DS_AP, DS_FP, DS_RL, DS_DL, DS_NF, DS_BA, DS_QS,
   560          DS_FC, DS_FN, DS_BS, DS_IN, DS_RG, DS_MQ, DS_TL, DS_RN,
   561          DS_NS, DS_NP, DS_TS, DS_MF, DS_CF, DS_RI, DS_RS, DS_PD,
   562          DS_HC, DS_SC, DS_BB, DS_QQ,
   563      };
   564      uint32_t orig_ds;
   565
   566      /*
   567       * Set the data_series bit field based on fd->required_fields
   568       * contents.
   569       */
   570      if (fd->required_fields && fd->required_fields != INT_MAX) {
   571          s->data_series = 0;
   572
   573          if (fd->required_fields & SAM_QNAME)
   574              s->data_series |= CRAM_RN;
   575
   576          if (fd->required_fields & SAM_FLAG)
   577              s->data_series |= CRAM_BF;
   578
   579          if (fd->required_fields & SAM_RNAME)
   580              s->data_series |= CRAM_RI | CRAM_BF;
   581
   582          if (fd->required_fields & SAM_POS)
   583              s->data_series |= CRAM_AP | CRAM_BF;
   584
   585          if (fd->required_fields & SAM_MAPQ)
   586              s->data_series |= CRAM_MQ;
   587
   588          if (fd->required_fields & SAM_CIGAR)
   589              s->data_series |= CRAM_CIGAR;
   590
   591          if (fd->required_fields & SAM_RNEXT)
   592              s->data_series |= CRAM_CF | CRAM_NF | CRAM_RI | CRAM_NS |CRAM_BF;
   593
   594          if (fd->required_fields & SAM_PNEXT)
   595              s->data_series |= CRAM_CF | CRAM_NF | CRAM_AP | CRAM_NP | CRAM_BF;
   596
   597          if (fd->required_fields & SAM_TLEN)
   598              s->data_series |= CRAM_CF | CRAM_NF | CRAM_AP | CRAM_TS |
   599                  CRAM_BF | CRAM_MF | CRAM_RI | CRAM_CIGAR;
   600
   601          if (fd->required_fields & SAM_SEQ)
   602              s->data_series |= CRAM_SEQ;
   603
   604          if (!(fd->required_fields & SAM_AUX))
   605              // No easy way to get MD/NM without other tags at present
   606              s->decode_md = 0;
   607
   608          if (fd->required_fields & SAM_QUAL)
   609              s->data_series |= CRAM_QUAL;
   610
   611          if (fd->required_fields & SAM_AUX)
   612              s->data_series |= CRAM_RG | CRAM_TL | CRAM_aux;
   613
   614          if (fd->required_fields & SAM_RGAUX)
   615              s->data_series |= CRAM_RG | CRAM_BF;
   616
   617          // Always uncompress CORE block
   618          if (cram_uncompress_block(s->block[0]))
   619              return -1;
   620      } else {
   621          s->data_series = CRAM_ALL;
   622
   623          for (i = 0; i < s->hdr->num_blocks; i++) {
   624              if (cram_uncompress_block(s->block[i]))
   625                  return -1;
   626          }
   627
   628          return 0;
   629      }
   630
   631      block_used = calloc(s->hdr->num_blocks+1, sizeof(int));
   632      if (!block_used)
   633          return -1;
   634
   635      do {
   636          /*
   637           * Also set data_series based on code prerequisites. Eg if we need
   638           * CRAM_QS then we also need to know CRAM_RL so we know how long it
   639           * is, or if we need FC/FP then we also need FN (number of features).
   640           *
   641           * It's not reciprocal though. We may be needing to decode FN
   642           * but have no need to decode FC, FP and cigar ops.
   643           */
   644          if (s->data_series & CRAM_RS)    s->data_series |= CRAM_FC|CRAM_FP;
   645          if (s->data_series & CRAM_PD)    s->data_series |= CRAM_FC|CRAM_FP;
   646          if (s->data_series & CRAM_HC)    s->data_series |= CRAM_FC|CRAM_FP;
   647          if (s->data_series & CRAM_QS)    s->data_series |= CRAM_FC|CRAM_FP;
   648          if (s->data_series & CRAM_IN)    s->data_series |= CRAM_FC|CRAM_FP;
   649          if (s->data_series & CRAM_SC)    s->data_series |= CRAM_FC|CRAM_FP;
   650          if (s->data_series & CRAM_BS)    s->data_series |= CRAM_FC|CRAM_FP;
   651          if (s->data_series & CRAM_DL)    s->data_series |= CRAM_FC|CRAM_FP;
   652          if (s->data_series & CRAM_BA)    s->data_series |= CRAM_FC|CRAM_FP;
   653          if (s->data_series & CRAM_BB)    s->data_series |= CRAM_FC|CRAM_FP;
   654          if (s->data_series & CRAM_QQ)    s->data_series |= CRAM_FC|CRAM_FP;
   655
   656          // cram_decode_seq() needs seq[] array
   657          if (s->data_series & (CRAM_SEQ|CRAM_CIGAR)) s->data_series |= CRAM_RL;
   658
   659          if (s->data_series & CRAM_FP)    s->data_series |= CRAM_FC;
   660          if (s->data_series & CRAM_FC)    s->data_series |= CRAM_FN;
   661          if (s->data_series & CRAM_aux)   s->data_series |= CRAM_TL;
   662          if (s->data_series & CRAM_MF)    s->data_series |= CRAM_CF;
   663          if (s->data_series & CRAM_MQ)    s->data_series |= CRAM_BF;
   664          if (s->data_series & CRAM_BS)    s->data_series |= CRAM_RI;
   665          if (s->data_series & (CRAM_MF |CRAM_NS |CRAM_NP |CRAM_TS |CRAM_NF))
   666              s->data_series |= CRAM_CF;
   667          if (!hdr->read_names_included && s->data_series & CRAM_RN)
   668              s->data_series |= CRAM_CF | CRAM_NF;
   669          if (s->data_series & (CRAM_BA | CRAM_QS | CRAM_BB | CRAM_QQ))
   670              s->data_series |= CRAM_BF | CRAM_CF | CRAM_RL;
   671
   672          orig_ds = s->data_series;
   673
   674          // Find which blocks are in use.
   675          for (i = 0; i < sizeof(i_to_id)/sizeof(*i_to_id); i++) {
   676              int bnum1, bnum2, j;
   677              cram_codec *c = hdr->codecs[i_to_id[i]];
   678
   679              if (!(s->data_series & (1<<i)))
   680                  continue;
   681
   682              if (!c)
   683                  continue;
   684
   685              bnum1 = cram_codec_to_id(c, &bnum2);
   686
   687              for (;;) {
   688                  switch (bnum1) {
   689                  case -2:
   690                      break;
   691
   692                  case -1:
   693                      core_used = 1;
   694                      break;
   695
   696                  default:
   697                      for (j = 0; j < s->hdr->num_blocks; j++) {
   698                          if (s->block[j]->content_type == EXTERNAL &&
   699                              s->block[j]->content_id == bnum1) {
   700                              block_used[j] = 1;
  3470   *        -1 on EOF or failure (check fd->err)
  3471   */
  3472  int cram_get_bam_seq(cram_fd *fd, bam_seq_t **bam) {
  3473      cram_record *cr;
  3474      cram_container *c;
  3475      cram_slice *s;
  3476
  3477      if (!(cr = cram_get_seq(fd)))
  3478          return -1;
  3479
  3480      c = fd->ctr;
  3481      s = c->slice;
  3482
  3483      return cram_to_bam(fd->header, fd, s, cr, s->curr_rec-1, bam);
  3484  }
