  3486  /*
  3487   * Drains and frees the decode read-queue for a multi-threaded reader.
  3488   */
  3489  void cram_drain_rqueue(cram_fd *fd) {
  3490      cram_container *lc = NULL;
  3491
  3492      if (!fd->pool || !fd->rqueue)
  3493          return;
  3494
  3495      // drain queue of any in-flight decode jobs
  3496      while (!hts_tpool_process_empty(fd->rqueue)) {
  3497          hts_tpool_result *r = hts_tpool_next_result_wait(fd->rqueue);
  3498          if (!r)
  3499              break;
  3500          cram_decode_job *j = (cram_decode_job *)hts_tpool_result_data(r);
  3501          if (j->c->slice == j->s)
  3502              j->c->slice = NULL;
  3503          if (j->c != lc) {
  3504              if (lc) {
  3505                  if (fd->ctr == lc)
  3506                      fd->ctr = NULL;
  3507                  if (fd->ctr_mt == lc)
  3508                      fd->ctr_mt = NULL;
  3509                  cram_free_container(lc);
  3510              }
  3511              lc = j->c;
  3512          }
  3513          cram_free_slice(j->s);
  3514          hts_tpool_delete_result(r, 1);
  3515      }
  3516
  3517      // Also tidy up any pending decode job that we didn't submit to the workers
  3518      // due to the input queue being full.
  3519      if (fd->job_pending) {
  3520          cram_decode_job *j = (cram_decode_job *)fd->job_pending;
  3521          if (j->c->slice == j->s)
  3522              j->c->slice = NULL;
  3523          if (j->c != lc) {
  3524              if (lc) {
  3525                  if (fd->ctr == lc)
  3526                      fd->ctr = NULL;
  3527                  if (fd->ctr_mt == lc)
  3528                      fd->ctr_mt = NULL;
  3529                  cram_free_container(lc);
  3530              }
  3531              lc = j->c;
  3532          }
  3533          cram_free_slice(j->s);
  3534          free(j);
  3535          fd->job_pending = NULL;
  3536      }
  3537
  3538      if (lc) {
  3539          if (fd->ctr == lc)
  3540              fd->ctr = NULL;
  3541          if (fd->ctr_mt == lc)
  3542              fd->ctr_mt = NULL;
  3543          cram_free_container(lc);
  3544      }
  3545  }
